param(
  [string]$ComposeFile = "compose.yaml",
  [string]$Site = "${env:FRAPPE_SITE_NAME}"
)

$ErrorActionPreference = 'Stop'
if ([string]::IsNullOrWhiteSpace($Site)) { $Site = 'recluta.localhost' }

docker compose -f $ComposeFile --profile erpnext up -d mariadb redis-cache redis-queue frappe
if ($LASTEXITCODE -ne 0) { throw 'No se pudo iniciar la infraestructura Frappe.' }

# Uses the official bench CLI inside the running image. No credentials or
# business data are generated by this script; database passwords come from .env.
docker compose -f $ComposeFile exec frappe bench --site $Site list-apps
if ($LASTEXITCODE -ne 0) {
  Write-Warning "El sitio $Site aún no existe o requiere inicialización con frappe_docker."
  exit 2
}

docker compose -f $ComposeFile exec frappe bench --site $Site install-app hrms
if ($LASTEXITCODE -ne 0) { throw 'La instalación de HRMS falló; revise los logs del servicio frappe.' }

docker compose -f $ComposeFile exec frappe bench --site $Site migrate
if ($LASTEXITCODE -ne 0) { throw 'La migración de Frappe/ERPNext/HRMS falló.' }

Write-Output "Frappe/ERPNext/HRMS verificados en $Site."
